import {useLocation, useNavigate, useParams} from 'react-router-dom';
import {useEffect, useState} from 'react';

function ItemDetail() {
    const {idArticle} = useParams();
    const location = useLocation();
    const navigate = useNavigate();
    const [itemDetail, setItemDetail] = useState(location.state?.item ?? {});
    const [selectedColor, setSelectedColor] = useState('');

    const defaultColors = ['Noir', 'Blanc', 'Bleu marine', 'Rouge'];
    const availableColors = itemDetail.colors?.length ? itemDetail.colors : defaultColors;

    const colorMap = {
        Noir: '#1f2937',
        Blanc: '#f3f4f6',
        'Bleu marine': '#1e3a8a',
        Rouge: '#dc2626'
    };

    useEffect(() => {
        if (location.state?.item) {
            setItemDetail(location.state.item);
            return;
        }

        if (!idArticle) return;

        fetch(`http://localhost:5000/api/items/${idArticle}`)
            .then((res) => {
                if (!res.ok) throw new Error('Erreur serveur');
                return res.json();
            })
            .then((data) => setItemDetail(data))
            .catch((error) => {
                console.error('Erreur récupération du détail vêtement :', error);
            });
    }, [idArticle, location.state]);

    return (
        <div>
            <h1>Détails du produit</h1>
            <p>Voici les détails du produit sélectionné.</p>
            <p>ID de l'article : {idArticle}</p>
            <p>{itemDetail.name}</p>
            <p>Prix : {itemDetail.price} euros</p>
            <p>Confort : {itemDetail.comfort}</p>
            <p>Taille : {itemDetail.size}</p>

            <p>Couleurs disponibles :</p>
            <div style={{display: 'flex', gap: '8px', flexWrap: 'wrap'}}>
                {availableColors.map((color) => (
                    <button
                        key={color}
                        onClick={() => setSelectedColor(color)}
                        style={{
                            backgroundColor: colorMap[color] ?? '#9ca3af',
                            color: color === 'Blanc' ? '#111827' : '#ffffff',
                            border: selectedColor === color ? '2px solid #111827' : '1px solid #d1d5db',
                            padding: '8px 12px',
                            borderRadius: '6px',
                            cursor: 'pointer'
                        }}
                    >
                        {color}
                    </button>
                ))}
            </div>
            {selectedColor && <p>Couleur sélectionnée : {selectedColor}</p>}

            <button
                onClick={() => navigate(-1)}
                style={{
                    marginTop: '16px',
                    padding: '8px 14px',
                    border: 'none',
                    borderRadius: '6px',
                    backgroundColor: '#111827',
                    color: '#ffffff',
                    cursor: 'pointer'
                }}
            >
                Fermer
            </button>
        </div>
    );
}

export default ItemDetail;
